package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string           // PIC X len=1 = "N"
var WsDiscount decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal      // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsCount int64              // PIC 9(3) len=3 = 0
var WsPriceEd string           // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string            // PIC ZZ,ZZ9.99 len=9
var WsNetEd string              // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string            // PIC ZZ,ZZZ,ZZ9.99 len=13

var discRec DiscRec

var discFile *os.File
var discReader *bufio.Reader
var eof bool

func formatEdited(val decimal.Decimal, picture string) string {
	// split picture at '.'
	dotIdx := strings.Index(picture, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		decPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	decDigits := 0
	for _, c := range decPic {
		if c == 'Z' || c == '9' {
			decDigits++
		}
	}

	// work with absolute value; COBOL pics here are unsigned
	if val.IsNegative() {
		val = val.Neg()
	}
	// truncate to required scale (value already has correct scale but ensure)
	val = val.Truncate(int32(decDigits))

	// integer part overflow truncation: keep low-order digits
	// integer part as integer
	intPart := val.Truncate(0)
	// get integer digits string (without sign)
	// Use decimal to string without exponent
	intStrRaw := intPart.StringFixed(0) // no exponent
	// intStrRaw may be "0" etc.
	// Remove possible minus already handled
	// Handle overflow: keep last intDigits chars
	// We need digit string padded to intDigits
	var digitStr string
	if len(intStrRaw) > intDigits {
		digitStr = intStrRaw[len(intStrRaw)-intDigits:]
	} else {
		digitStr = strings.Repeat("0", intDigits-len(intStrRaw)) + intStrRaw
	}

	// Build integer edited part
	intChars := []rune(intPic)
	resInt := make([]rune, len(intChars))
	suppressed := true
	digitIdx := 0
	for i, c := range intChars {
		if c == ',' {
			if suppressed {
				resInt[i] = ' '
			} else {
				resInt[i] = ','
			}
		} else if c == 'Z' || c == '9' {
			d := rune(digitStr[digitIdx])
			digitIdx++
			if c == 'Z' {
				if suppressed && d == '0' {
					resInt[i] = ' '
					// stay suppressed
				} else {
					resInt[i] = d
					suppressed = false
				}
			} else { // '9'
				resInt[i] = d
				suppressed = false
			}
		} else {
			resInt[i] = c
		}
	}

	if decDigits == 0 {
		return string(resInt)
	}
	// fractional part
	// extract fractional digits
	// val = intPart + frac/10^decDigits
	fracPart := val.Sub(intPart)
	// shift to integer
	// fracPart * 10^decDigits
	pow := decimal.NewFromInt(1)
	for i := 0; i < decDigits; i++ {
		pow = pow.Mul(decimal.NewFromInt(10))
	}
	fracInt := fracPart.Mul(pow).Truncate(0)
	fracStrRaw := fracInt.StringFixed(0)
	// fracStrRaw may be negative? no
	// pad leading zeros to decDigits
	if len(fracStrRaw) < decDigits {
		fracStrRaw = strings.Repeat("0", decDigits-len(fracStrRaw)) + fracStrRaw
	} else if len(fracStrRaw) > decDigits {
		fracStrRaw = fracStrRaw[len(fracStrRaw)-decDigits:]
	}
	return string(resInt) + "." + fracStrRaw
}

func formatUneditedInt(v int64, digits int) string {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if mod != 0 {
		// keep low-order digits, handle negative?
		v = v % mod
		if v < 0 {
			v += mod
		}
	}
	return fmt.Sprintf("%0*d", digits, v)
}

func storePic9V99(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// truncate toward zero to scale
	v = v.Truncate(scale)
	// overflow: keep low-order digits
	// total digits = intDigits + scale
	totalDigits := intDigits + int(scale)
	// Create modulus = 10^intDigits for integer part + fractional part unchanged? Actually low-order digits means integer overflow wraps.
	// Equivalent to v mod 10^intDigits (with scale)
	// Compute via integer representation: iv = trunc(v * 10^scale)
	pow := decimal.NewFromInt(1)
	for i := int32(0); i < scale; i++ {
		pow = pow.Mul(decimal.NewFromInt(10))
	}
	iv := v.Mul(pow).Truncate(0) // integer
	modPow := decimal.NewFromInt(1)
	for i := 0; i < totalDigits; i++ {
		modPow = modPow.Mul(decimal.NewFromInt(10))
	}
	// keep sign
	neg := iv.IsNegative()
	if neg {
		iv = iv.Neg()
	}
	// iv mod 10^totalDigits
	iv = iv.Mod(modPow)
	if neg {
		iv = iv.Neg()
	}
	return iv.Div(pow)
}

func parsePriceField(s string) decimal.Decimal {
	// s is 7 digits, may contain spaces? Assume digits, if spaces treat as 0
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// keep only digits; if spaces inside? COBOL numeric fields padded with spaces? But we pad line.
	// Remove spaces
	clean := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		return decimal.Zero
	}
	// parse as integer then shift -2
	d, err := decimal.NewFromString(clean)
	if err != nil {
		return decimal.Zero
	}
	return d.Shift(-2)
}

func parsePctField(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	clean := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		return 0
	}
	var v int64
	fmt.Sscan(clean, &v)
	// keep low-order 2 digits
	v = v % 100
	if v < 0 {
		v += 100
	}
	return v
}

func readPara() {
	if eof {
		WsEofFlag = "Y"
		return
	}
	line, err := discReader.ReadString('\n')
	if err != nil {
		// EOF or other
		if len(line) == 0 {
			eof = true
			WsEofFlag = "Y"
			return
		}
		// last line without newline, still process
	}
	// strip trailing \r\n
	line = strings.TrimRight(line, "\r\n")
	// pad with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// parse fields 0-based
	drItemRaw := line[0:6]
	drPriceRaw := line[6:13]
	drPctRaw := line[13:15]

	discRec.DrItem = drItemRaw
	discRec.DrPrice = parsePriceField(drPriceRaw)
	discRec.DrPct = parsePctField(drPctRaw)

	// check if we hit EOF after this read: next read will detect
	if err != nil && err.Error() == "EOF" {
		// we have processed the line, next call will be EOF
		// Need to know if underlying reader is at EOF: we set flag to check next read
		// For simplicity, detect next read returns EOF, so we peek
		// Instead, we rely on next call to ReadString returning error with 0 bytes
		// So keep eof false until next call, but we have consumed last line
		// To know EOF, peek
		// Use helper: if we got io.EOF, set a pending EOF flag for next call
		// We'll set eofPending
		pendingEOF = true
	}
}

var pendingEOF bool

func readParaWrapper() {
	if pendingEOF {
		// we already consumed last line; now signal EOF on next read
		// Actually COBOL READ at end sets flag after attempting to read beyond last record
		// So after processing last record, next READ should set INPUT-DONE
		// Our logic: after processing record, we call READ-PARA again, which should hit EOF
		if eofNext {
			WsEofFlag = "Y"
			eof = true
			return
		}
		eofNext = true
		return
	}
	// normal read
	if eofNext {
		WsEofFlag = "Y"
		eof = true
		return
	}
	line, err := discReader.ReadString('\n')
	if err != nil {
		if len(line) == 0 {
			WsEofFlag = "Y"
			eof = true
			return
		}
		// line has content but EOF after it
		line = strings.TrimRight(line, "\r\n")
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		discRec.DrItem = line[0:6]
		discRec.DrPrice = parsePriceField(line[6:13])
		discRec.DrPct = parsePctField(line[13:15])
		eofNext = true
		return
	}
	line = strings.TrimRight(line, "\r\n")
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	discRec.DrItem = line[0:6]
	discRec.DrPrice = parsePriceField(line[6:13])
	discRec.DrPct = parsePctField(line[13:15])
}

var eofNext bool

func mainPara() {
	var err error
	discFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer discFile.Close()
	discReader = bufio.NewReader(discFile)
	WsEofFlag = "N"
	eof = false
	eofNext = false
	pendingEOF = false
	WsDiscount = decimal.Zero
	WsNet = decimal.Zero
	WsTotalNet = decimal.Zero
	WsCount = 0

	readParaWrapper()
	for WsEofFlag != "Y" {
		processPara()
	}
	closeDiscFile()
	summaryPara()
}

func closeDiscFile() {
	// CLOSE DISC-FILE
}

func processPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	prod := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct))
	// divide by 100 -> Shift(-2) exact
	quot := prod.Shift(-2)
	rounded := quot.Round(2)
	WsDiscount = storePic9V99(rounded, 5, 2)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	netVal := discRec.DrPrice.Sub(WsDiscount).Truncate(2)
	WsNet = storePic9V99(netVal, 5, 2)

	// ADD WS-NET TO WS-TOTAL-NET
	WsTotalNet = WsTotalNet.Add(WsNet)
	WsTotalNet = WsTotalNet.Truncate(2)
	// overflow handling for 9(8)V99
	WsTotalNet = storePic9V99(WsTotalNet, 8, 2)

	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 1000

	// MOVE ... TO edited
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	pctStr := formatUneditedInt(discRec.DrPct, 2)
	// DR-ITEM is exactly 6 chars
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)

	readParaWrapper()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsCount, 3)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	mainPara()
}

